        //Source: Real-Time Collision Detection by Christer Ericson
        //Reference: Page 177
        float3 m = rayPosition - spherePosition;

        float b = dot(m, rayDirection);
        float c = dot(m, m) - (sphereRadius * sphereRadius);

        if (c > 0 && b > 0)
