            distance = 0;
            return false;
        }

        float discriminant = b * b - c;

        if (discriminant < 0)
        {
            distance = 0;
            return false;
        }

        distance = -b - sqrt(discriminant);

        if (distance < 0)
            distance = 0;

        return true;
    }


